cat <<'EOF' > app/javascript/helpers/i18n_helpers.js
import { getMetaContent } from "helpers/meta_helpers"

let cachedRaw
let cachedData

function loadI18nData() {
  const raw = getMetaContent("i18n")
  if (raw !== cachedRaw) {
    cachedRaw = raw
    try {
      cachedData = raw ? JSON.parse(raw) : {}
    } catch {
      cachedData = {}
    }
  }
  return cachedData || {}
}

export function currentLocale() {
  return loadI18nData().locale || document.documentElement.lang || "en"
}

export function intlLocale() {
  return loadI18nData().intl_locale || "en-US"
}

export function t(key, replacements = {}) {
  const value = lookup(key)
  if (typeof value !== "string") return key

  return value.replace(/%\{(\w+)\}/g, (_, name) => {
    return Object.prototype.hasOwnProperty.call(replacements, name) ? replacements[name] : `%{${name}}`
  })
}

export function tCount(key, count, replacements = {}) {
  const pluralKey = count === 1 ? `${key}.one` : `${key}.other`
  return t(pluralKey, { count, ...replacements })
}

function lookup(key) {
  return key.split(".").reduce((obj, part) => (obj && obj[part] !== undefined ? obj[part] : undefined), loadI18nData())
}
EOF

cat <<'EOF' > app/javascript/controllers/local_time_controller.js
import { Controller } from "@hotwired/stimulus"
import { differenceInDays, secondsToDate } from "helpers/date_helpers"
import { currentLocale, intlLocale, t, tCount } from "helpers/i18n_helpers"

export default class extends Controller {
  static targets = [ "time", "date", "datetime", "shortdate", "ago", "indays", "daysago", "agoorweekday", "timeordate" ]
  static values = { refreshInterval: Number }
  static classes = [ "local-time-value"]

  #timer
  #locale

  initialize() {
    this.#initFormatters()
  }

  connect() {
    document.documentElement.lang = currentLocale()
    this.#timer = setInterval(() => this.#refreshRelativeTimes(), 30_000)
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  refreshAll() {
    this.#syncLocale()
    this.constructor.targets.forEach(targetName => {
      this.targets.findAll(targetName).forEach(target => {
        this.#formatTime(this[`${targetName}Formatter`], target)
      })
    })
  }

  refreshTarget(event) {
    this.#syncLocale()
    const target = event.target;
    const targetName = target.dataset.localTimeTarget
    this.#formatTime(this[`${targetName}Formatter`], target)
  }

  timeTargetConnected(target) {
    this.#formatTime(this.timeFormatter, target)
  }

  dateTargetConnected(target) {
    this.#formatTime(this.dateFormatter, target)
  }

  datetimeTargetConnected(target) {
    this.#formatTime(this.datetimeFormatter, target)
  }

  shortdateTargetConnected(target) {
    this.#formatTime(this.shortdateFormatter, target)
  }

  agoTargetConnected(target) {
    this.#formatTime(this.agoFormatter, target)
  }

  indaysTargetConnected(target) {
    this.#formatTime(this.indaysFormatter, target)
  }

  daysagoTargetConnected(target) {
    this.#formatTime(this.daysagoFormatter, target)
  }

  agoorweekdayTargetConnected(target) {
    this.#formatTime(this.agoorweekdayFormatter, target)
  }

  timeordateTargetConnected(target) {
    this.#formatTime(this.timeordateFormatter, target)
  }

  #syncLocale() {
    document.documentElement.lang = currentLocale()
    if (this.#locale !== intlLocale()) {
      this.#initFormatters()
    }
  }

  #initFormatters() {
    const locale = intlLocale()
    this.#locale = locale
    this.timeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short" })
    this.dateFormatter = new Intl.DateTimeFormat(locale, { dateStyle: "long" })
    this.shortdateFormatter = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" })
    this.datetimeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short", dateStyle: "short" })
    this.agoFormatter = new AgoFormatter()
    this.daysagoFormatter = new DaysAgoFormatter()
    this.datewithweekdayFormatter = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" })
    this.indaysFormatter = new InDaysFormatter()
    this.agoorweekdayFormatter = new DaysAgoOrWeekdayFormatter(locale)
    this.timeordateFormatter = new TimeOrDateFormatter(locale)
  }

  #refreshRelativeTimes() {
    this.agoTargets.forEach(target => {
      this.#formatTime(this.agoFormatter, target)
    })
  }

  #formatTime(formatter, target) {
    const dt = secondsToDate(parseInt(target.getAttribute("datetime")))
    target.innerHTML = formatter.format(dt)
    target.title = this.datetimeFormatter.format(dt)
  }
}

class AgoFormatter {
  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#pluralize("year", years)
    if (months >= 1) return this.#pluralize("month", months)
    if (weeks >= 1) return this.#pluralize("week", weeks)
    if (days >= 1) return this.#pluralize("day", days)
    if (hours >= 1) return this.#pluralize("hour", hours)
    if (minutes >= 1) return this.#pluralize("minute", minutes)

    return t("local_time.ago.less_than_a_minute")
  }

  #pluralize(unit, quantity) {
    quantity = Math.floor(quantity)
    return tCount(`local_time.ago.${unit}`, quantity)
  }
}

class DaysAgoFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 0) return styleableValue(t("local_time.days_ago.today"))
    if (days === 1) return styleableValue(t("local_time.days_ago.yesterday"))
    return t("local_time.days_ago.days_ago", { days: styleableValue(days) })
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter().format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

class InDaysFormatter {
  format(date) {
    const days = differenceInDays(new Date(), date)

    if (days <= 0) return styleableValue(t("local_time.in_days.today"))
    if (days === 1) return styleableValue(t("local_time.in_days.tomorrow"))
    return t("local_time.in_days.in_days", { days: styleableValue(days) })
  }
}

class TimeOrDateFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(this.locale, { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { timeStyle: "short" }).format(date)
    }
  }
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
EOF

cat <<'EOF' > app/javascript/controllers/bubble_controller.js
import { Controller } from "@hotwired/stimulus"
import { signedDifferenceInDays } from "helpers/date_helpers"
import { t, tCount } from "helpers/i18n_helpers"

const REFRESH_INTERVAL = 3_600_000 // 1 hour (in milliseconds)

export default class extends Controller {
  static targets = [ "entropy", "stalled", "top", "center", "bottom" ]
  static values = { entropy: Object, stalled: Object }

  #timer

  connect() {
    this.#timer = setInterval(this.update.bind(this), REFRESH_INTERVAL)
    this.update()
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  update() {
    if (this.#hasEntropy) {
      this.#showEntropy()
    } else if (this.#isStalled) {
      this.#showStalled()
    } else {
      this.#hide()
    }
  }

  get #hasEntropy() {
    return this.#entropyCleanupInDays < this.entropyValue.daysBeforeReminder
  }

  get #entropyCleanupInDays() {
    return signedDifferenceInDays(new Date(), new Date(this.entropyValue.closesAt))
  }

  #showEntropy() {
    const days = this.#entropyCleanupInDays
    this.#render({
      top: days < 1 ? t("bubble.entropy.today_top", { action: this.entropyValue.action }) : t("bubble.entropy.in_days_top", { action: this.entropyValue.action }),
      center: days < 1 ? "!" : days,
      bottom: days < 1 ? t("bubble.entropy.today_bottom") : tCount("bubble.entropy.day", days),
    })
  }

  #render({ top, center, bottom }) {
    this.topTarget.innerHTML = top
    this.centerTarget.innerHTML = center
    this.bottomTarget.innerHTML = bottom

    this.#show()
  }

  // Keep in sync with Card::Stallable#stalled? in app/models/card/stallable.rb
  get #isStalled() {
    return this.stalledValue.lastActivitySpikeAt &&
      signedDifferenceInDays(new Date(this.stalledValue.lastActivitySpikeAt), new Date()) > this.stalledValue.stalledAfterDays &&
      signedDifferenceInDays(new Date(this.stalledValue.updatedAt), new Date()) > this.stalledValue.stalledAfterDays
  }

  #showStalled() {
    const days = signedDifferenceInDays(new Date(this.stalledValue.lastActivitySpikeAt), new Date())
    this.#render({
      top: t("bubble.stalled.top"),
      center: days,
      bottom: tCount("bubble.stalled.day", days)
    })
  }

  #hide() {
    this.element.toggleAttribute("hidden", true)
  }

  #show() {
    this.element.removeAttribute("hidden")
  }
}
